{
  "items": [
    {
      "name": "MvPolynomial.totalDegree_le_degrees_card",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R), p.totalDegree ≤ p.degrees.card"
    },
    {
      "name": "MvPolynomial.IsHomogeneous.totalDegree_le",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R] {φ : MvPolynomial σ R} {n : ℕ},\n  φ.IsHomogeneous n → φ.totalDegree ≤ n"
    },
    {
      "name": "MvPolynomial.totalDegree_finsetSum_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {ι : Type u_3} {s : Finset ι} {f : ι → MvPolynomial σ R} {d : ℕ},\n  (∀ i ∈ s, (f i).totalDegree ≤ d) → (s.sum f).totalDegree ≤ d"
    },
    {
      "name": "MvPolynomial.totalDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → ℕ"
    },
    {
      "name": "MvPolynomial.totalDegree_monomial_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (s : σ →₀ ℕ) (c : R),\n  ((MvPolynomial.monomial s) c).totalDegree ≤ s.sum fun x => id"
    }
  ]
}
